from base.exceptions import EntityBadRequestErrorfrom base.service import BaseServicefrom helpers.search import Paginationfrom entities.container import Containerfrom entities.container import ContainerType as ctfrom repositories.container import ContainerRepositoryfrom schemas.channel import ChannelCreatefrom services.container import ContainerServicefrom services.join_request import JoinRequestServicefrom services.subscribe import SubscribeServicefrom sqlalchemy.ext.asyncio import AsyncSessionfrom user import Userfrom utils.post import generate_slugchannels = [    ct.public_channel,    ct.private_channel]def check_container_type(_type: ct | list[ct]):    def decorator(func):        def wrapper(*args, container: Container, **kwargs):            if isinstance(_type, list):                for i in _type:                    if i == container.type:                        return func(*args, container=container, **kwargs)            if container.type != _type:                raise EntityBadRequestError(f"not {_type} container")            return func(*args, container=container, **kwargs)        return wrapper    return decoratordef only_owner(func):    def wrapper(*args, user: User, container: Container, **kwargs):        if user.id != container.author_id:            raise EntityBadRequestError("вы не админ канала")        return func(*args, container=container, user=user, **kwargs)    return wrappercheck_private = check_container_type(ct.private_channel)check_public = check_container_type(ct.public_channel)class _PublicChannelService(BaseService[Container, ContainerRepository]):    def __init__(self, session: AsyncSession):        super().__init__(Container, session, ContainerRepository)        self.s = ContainerService(session)        self.subs_service = SubscribeService(session)    @check_public    async def subscribe(self, user: User, container: Container):        await self.subs_service.create_subscribe(user=user, container_id=container.id)class _PrivateChannelService(BaseService[Container, ContainerRepository]):    def __init__(self, session: AsyncSession):        super().__init__(Container, session, ContainerRepository)        self.c = ContainerService(session)        self.jr_service = JoinRequestService(session)        self.subs_service = SubscribeService(session)    @check_public    async def process_subscribe(self, user: User, container: Container):        await self.subs_service.create_subscribe(            user=user, container_id=container.id        )    async def send_jr(self, user: User, container: Container):        await self.subs_service.check_already_exists(user_id=user.id, container_id=container.id)        await self.jr_service.send_jr(user=user, channel=container)    async def process_jr(            self, user: User,            jr_id: int, approve: bool    ):        jr = await self.jr_service.get_item_by_id(jr_id)        channel = await self.c.get_item_by_id(jr.container_id)        if channel.author_id != user.id:            raise EntityBadRequestError("sub")        if approve:            await self.subs_service.create_subscribe(                user=user, container_id=jr.container_id            )        await self.jr_service.delete_item(jr)    @check_private    @only_owner    async def get_jrs(self, user: User, container: Container, pagination: Pagination):        return await self.jr_service.get_items_by(            container_id=container.id,            pagination=pagination        )class ChannelService(BaseService[Container, ContainerRepository]):    def __init__(self, session: AsyncSession):        super().__init__(Container, session, ContainerRepository)        self.public = _PublicChannelService(session)        self.private = _PrivateChannelService(session)    async def create_channel(self, user: User, channel: ChannelCreate) -> Container:        await self.check_already_exists(            slug=channel.slug, type=channels        )        channel.slug = generate_slug(channel.slug)        return await self.create_item(            author_id=user.id, **channel.dict(), type=channels[channel.is_private]        )    async def get_channel(self, slug: str) -> Container:        return await self.get_by_or_raise(slug=slug, type=channels)    @only_owner    async def get_subscribers(            self, user: User,            container: Container,            pagination: Pagination    ):        return await self.private.subs_service.get_items_by(pagination=pagination, container_id=container.id)